def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Find first difference
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            # Check if we're inserting or replacing
            if len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion case  
                return (s_in[i], '', i)
            else:
                # Replacement case
                return (s_in[i], s_out[i], i)

    # If strings are same length and we reach here, check if one is longer
    if len(s_in) < len(s_out):
        return (s_in[-1] if s_in else '', s_out[-1], len(s_in)-1)
    elif len(s_in) > len(s_out):
        return (s_in[-1], '', len(s_in)-1)
    else:
        return ('', '', -1)

